(3283916, 458618, 62727, '<td valign="top">Cool idea! 8</td>', 'Cool idea! 8', '2007-01-26 00:49:52.000000', NULL, 1),
(3283920, 457702, 45672, '<td valign="top">Tank you for tanking this picture.  I hope your score isn''t in the tank.  Ok, ok, enough.  Nice perspective in this picture.  Nothing like looking down the business end of a killing machine.  I wish the forklift wasn''t sitting behind it, but you might not have had the option of moving it.  Nice capture.</td>', 'Tank you for tanking this picture.  I hope your score isn''t in the tank.  Ok, ok, enough.  Nice perspective in this picture.  Nothing like looking down the business end of a killing machine.  I wish the forklift wasn''t sitting behind it, but you might not have had the option of moving it.  Nice capture.', '2007-01-26 00:50:46.000000', NULL, 1),
(3283921, 456130, 62727, '<td valign="top">ROFLOL!!  Awesome! 10</td>', 'ROFLOL!!  Awesome! 10', '2007-01-26 00:50:47.000000', NULL, 1),
