(3303489, 458293, 66348, '<td valign="top">Just beautiful shot, love the winter and how clean it makes the earth look. I think you too a great shot of showing that. Very nicely done.</td>', 'Just beautiful shot, love the winter and how clean it makes the earth look. I think you too a great shot of showing that. Very nicely done.', '2007-01-30 14:52:27.000000', NULL, 1),
(3303494, 457273, 66348, '<td valign="top">Sweet setup. Love the colors and idea behind the shot. Very nicely done.</td>', 'Sweet setup. Love the colors and idea behind the shot. Very nicely done.', '2007-01-30 14:53:56.000000', NULL, 1),
