(3304132, 458423, 3087, '<td valign="top">Lovely shapes and textures which make an interesting black and white study but it''s lacking a real focal point or hook to really pull me in.</td>', 'Lovely shapes and textures which make an interesting black and white study but it''s lacking a real focal point or hook to really pull me in.', '2007-01-30 18:00:49.000000', NULL, 1),
(3304139, 458229, 3087, '<td valign="top">Really like your choice of perspective/ viewpoint to make the star statue such a huge part of the image and provide a frame for the main building behind. Works really well.</td>', 'Really like your choice of perspective/ viewpoint to make the star statue such a huge part of the image and provide a frame for the main building behind. Works really well.', '2007-01-30 18:01:36.000000', NULL, 1),
(3304145, 457537, 3087, '<td valign="top">Sweet close-up; the essence of simplicity and innocence. Don''t like the "painted" effect but do love the image, the crop/composition and the high key nature.</td>', 'Sweet close-up; the essence of simplicity and innocence. Don''t like the "painted" effect but do love the image, the crop/composition and the high key nature.', '2007-01-30 18:02:36.000000', NULL, 1),
(3304150, 458685, 3087, '<td valign="top">Cool - interesting abstract. I like the shallow DOF but not sure about composition in terms of position of the focal point sworl within the frame.</td>', 'Cool - interesting abstract. I like the shallow DOF but not sure about composition in terms of position of the focal point sworl within the frame.', '2007-01-30 18:04:19.000000', NULL, 1),
(3304154, 458472, 3087, '<td valign="top">Wow, interesting way of framing... I don''t like the choice of fur-lined hood - I think the texture of that fur detracts from the smoke itself framing the face. Like the way the detail and light is clear around his eyes.</td>', 'Wow, interesting way of framing... I don''t like the choice of fur-lined hood - I think the texture of that fur detracts from the smoke itself framing the face. Like the way the detail and light is clear around his eyes.', '2007-01-30 18:05:36.000000', NULL, 1),
(3304157, 457504, 3087, '<td valign="top">Nice tight portrait - infact the tightness itself adds an edginess and immediacy to the shot. Not keen on the border treatment.</td>', 'Nice tight portrait - infact the tightness itself adds an edginess and immediacy to the shot. Not keen on the border treatment.', '2007-01-30 18:06:24.000000', NULL, 1),
(3304158, 458734, 3087, '<td valign="top">Beautiful portrait - the lighting and composition really bring out the colours, texture and intricacy of the instrument. What beautiful handiwork and beautifully captured too.</td>', 'Beautiful portrait - the lighting and composition really bring out the colours, texture and intricacy of the instrument. What beautiful handiwork and beautifully captured too.', '2007-01-30 18:07:03.000000', NULL, 1),
