(3315660, 458513, 50695, '<td valign="top">perfect urban image. 10</td>', 'perfect urban image. 10', '2007-02-01 21:13:33.000000', NULL, 1),
(3315672, 458639, 50695, '<td valign="top">I find the perspective, and the parallel shapes of apple and face, to be very appealling. I know I don''t usually like selective desaturation, but it is perfectly applied here. a bold, disorienting image that offers me a rare treat. 10</td>', 'I find the perspective, and the parallel shapes of apple and face, to be very appealling. I know I don''t usually like selective desaturation, but it is perfectly applied here. a bold, disorienting image that offers me a rare treat. 10', '2007-02-01 21:15:38.000000', NULL, 1),
(3315690, 458734, 50695, '<td valign="top">this is like a tribute to Cubism. Some of the first movements toward Abstract Art, including Cubism, utilized the sensuous shapes of violins and other string instruments, probably for the musical connotations as much as the visual beauty. I find it thrilling to see you do the same thing via the purely representational medium of photography. 10</td>', 'this is like a tribute to Cubism. Some of the first movements toward Abstract Art, including Cubism, utilized the sensuous shapes of violins and other string instruments, probably for the musical connotations as much as the visual beauty. I find it thrilling to see you do the same thing via the purely representational medium of photography. 10', '2007-02-01 21:18:08.000000', NULL, 1),
(3315693, 458187, 50695, '<td valign="top">I love the way you disappear behind the bear! I don''t if it''s poignant or just plain scary. 8</td>', 'I love the way you disappear behind the bear! I don''t if it''s poignant or just plain scary. 8', '2007-02-01 21:18:52.000000', NULL, 1),
